import json

# Example JSON payload for logging
payload = json.dumps({"message": "This is a test log message"})

# Simulate a POST request to log a message
def simulate_post_request(payload):
    try:
        data = json.loads(payload)
        message = data.get('message', '')
        if message:
            print(f"Log message: {message}")
        else:
            print("Error: No message provided")
    except json.JSONDecodeError:
        print("Error: Invalid JSON")

simulate_post_request(payload)
